#include <iostream>
#include <cstdio>
#include <cstring>
#include <string>
#include <algorithm>
#include <queue>
#include <map>
#include <set>
#include <cstdlib>
#include <vector>
using namespace std;

const int MAXN = 200;
const int MAXM = 100000;
const int INF = 199999999;

int grid[20][20];
int graph[MAXN][MAXN];
int n, N, T;
string line;
int humans[MAXN][3];
int robots[MAXN][3];
int zr, zc;
int cx, cy;
int dirs[4][2] = {{0,-1},{0,1},{-1,0},{1,0}};

int isValid(int r, int c) {
    if (r > 0 && r <= n && c > 0 && c <= n && grid[r][c] != -1)
        return (r-1)*n + c;
    return -1;
}

void buildGraph() {
    N = n * n;
    memset(graph, -1, sizeof(graph));
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= n; ++c) {
            if (grid[r][c] == -1) continue;
            int p = (r-1)*n + c;
            graph[p][p] = 0;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dirs[d][0];
                int nc = c + dirs[d][1];
                if (nr > 0 && nr <= n && nc > 0 && nc <= n && grid[nr][nc] != -1) {
                    int np = (nr-1)*n + nc;
                    graph[p][np] = 1;
                }
            }
        }
    }
}

vector<int> dist;
vector<int> q;
vector<bool> inq;

void spfa() {
    dist.assign(N+1, INF);
    inq.assign(N+1, false);
    q.clear();
    int start = (zr-1)*n + zc;
    dist[start] = 0;
    q.push_back(start);
    inq[start] = true;
    int front = 0;
    while (front < (int)q.size()) {
        int u = q[front++];
        inq[u] = false;
        for (int v = 1; v <= N; ++v) {
            if (graph[u][v] == 1 && dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                if (!inq[v]) {
                    q.push_back(v);
                    inq[v] = true;
                }
            }
        }
    }
}

void floyd() {
    for (int k = 1; k <= N; ++k) {
        for (int i = 1; i <= N; ++i) {
            if (graph[i][k] == -1) continue;
            for (int j = 1; j <= N; ++j) {
                if (graph[k][j] == -1) continue;
                if (graph[i][j] == -1 || graph[i][j] > graph[i][k] + graph[k][j])
                    graph[i][j] = graph[i][k] + graph[k][j];
            }
        }
    }
}

struct Edge {
    int st, ed, flow, next;
};
vector<Edge> edges;
vector<int> head;
int E;
int src, dest;

void addEdge(int st, int ed, int flow) {
    edges.push_back({st, ed, flow, head[st]});
    head[st] = E++;
    edges.push_back({ed, st, 0, head[ed]});
    head[ed] = E++;
}

void buildFlow() {
    head.assign(cx+cy+2, -1);
    edges.clear();
    E = 0;
    src = 0;
    dest = cx + cy + 1;
    for (int i = 1; i <= cx; ++i)
        addEdge(src, i, humans[i][2]);
    for (int i = 1; i <= cy; ++i)
        addEdge(cx + i, dest, robots[i][2]);
    for (int i = 1; i <= cx; ++i) {
        for (int j = 1; j <= cy; ++j) {
            int p1 = (humans[i][0]-1)*n + humans[i][1];
            int p2 = (robots[j][0]-1)*n + robots[j][1];
            if (graph[p1][p2] != -1 && graph[p1][p2] <= T && graph[p1][p2] < dist[p2]) {
                addEdge(i, cx + j, INF);
            } else if (graph[p1][p2] != -1 && graph[p1][p2] <= T && graph[p1][p2] == dist[p2]) {
                for (int d = 0; d < 4; ++d) {
                    int rr = robots[j][0] + dirs[d][0];
                    int cc = robots[j][1] + dirs[d][1];
                    int pp = isValid(rr, cc);
                    if (pp != -1) {
                        if (graph[p1][pp] == graph[p1][p2] - 1 && graph[p1][pp] < dist[pp]) {
                            addEdge(i, cx + j, INF);
                        }
                    }
                }
            }
        }
    }
}

vector<int> level;
vector<int> cur;

bool dinicBFS() {
    level.assign(dest+1, -1);
    queue<int> q;
    q.push(src);
    level[src] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].ed;
            if (level[v] == -1 && edges[i].flow > 0) {
                level[v] = level[u] + 1;
                if (v == dest) return true;
                q.push(v);
            }
        }
    }
    return false;
}

int dinicDFS(int u, int flow) {
    if (u == dest) return flow;
    for (int &i = cur[u]; i != -1; i = edges[i].next) {
        int v = edges[i].ed;
        if (level[v] == level[u] + 1 && edges[i].flow > 0) {
            int pushed = dinicDFS(v, min(flow, edges[i].flow));
            if (pushed > 0) {
                edges[i].flow -= pushed;
                edges[i^1].flow += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic() {
    int flow = 0;
    while (dinicBFS()) {
        cur = head;
        while (int pushed = dinicDFS(src, INF))
            flow += pushed;
    }
    return flow;
}

int solve() {
    grid[zr][zc] = 0;
    buildGraph();
    spfa();
    grid[zr][zc] = -1;
    buildGraph();
    floyd();
    buildFlow();
    return dinic();
}

int main() {
    cin >> n >> T;
    cx = cy = 0;
    memset(grid, 0, sizeof(grid));
    for (int i = 1; i <= n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] == 'Y') grid[i][j+1] = -1;
            else if (line[j] == 'Z') {
                zr = i; zc = j+1;
                grid[i][j+1] = -1;
            } else if (line[j] > '0' && line[j] <= '9') {
                humans[++cx][0] = i;
                humans[cx][1] = j+1;
                humans[cx][2] = line[j] - '0';
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] > '0' && line[j] <= '9') {
                robots[++cy][0] = i;
                robots[cy][1] = j+1;
                robots[cy][2] = line[j] - '0';
            }
        }
    }
    cout << solve() << endl;
    return 0;
}
